with ZipFile(SOURCE) as z: parts={n:z.read(n) for n in z.namelist()}
doc=D.parseString(parts['word/document.xml']);ps=list(doc.getElementsByTagName('w:p'))
def text(p):return ''.join(n.firstChild.data if n.firstChild else '' for n in p.getElementsByTagName('w:t'))
before=[text(p) for p in ps]
for i,value in replacements.items():
 p=ps[i]
 runs=p.getElementsByTagName('w:r');rp=None
 if runs:
  props=runs[0].getElementsByTagName('w:rPr')
  if props:rp=props[0].cloneNode(True)
 for child in list(p.childNodes):
  if child.nodeName!='w:pPr':p.removeChild(child)
 for j,chunk in enumerate(value.split('\t')):
  r=doc.createElement('w:r')
  if rp:r.appendChild(rp.cloneNode(True))
  if j:r.appendChild(doc.createElement('w:tab'))
  if chunk:
   t=doc.createElement('w:t');t.setAttribute('xml:space','preserve');t.appendChild(doc.createTextNode(chunk));r.appendChild(t)
  p.appendChild(r)
parts['word/document.xml']=doc.toxml(encoding='UTF-8')
# Refresh only descriptive metadata; retain the template formatting and signature table.
core=D.parseString(parts['docProps/core.xml'])
for key,val in [('dc:title',f'Договор подряда № {number} — Печать заказов — Дисквер'),('dc:subject','Создание страницы «Печать заказов»'),('cp:keywords','')]:
 nodes=core.getElementsByTagName(key)
 if nodes:
  node=nodes[0]
  for c in list(node.childNodes):node.removeChild(c)
  node.appendChild(core.createTextNode(val))
parts['docProps/core.xml']=core.toxml(encoding='UTF-8')
output=ROOT/(f'Договор_{number}_Печать_заказов_Дисквер_11.11.2026.docx' if terms else 'Проект_договора_Печать_заказов_Дисквер.docx')
with ZipFile(output,'w',ZIP_DEFLATED) as z:
 for n,b in parts.items():z.writestr(n,b)
after=[text(p) for p in ps]
assert all(before[i]==after[i] for i in range(len(ps)) if i not in replacements)
assert before[3:5]==after[3:5] and before[80:]==after[80:]
full='\n'.join(after)
assert not re.search(r'Кэшфлоу|bi\.metaverseworld|336 000|168 000|октября|Яндекс|Мой\s*Склад|ЦИФРОВОЙ',full,re.I)
assert '«11» ноября 2026 г.' in full
if terms:assert not re.search(r'\[(НОМЕР|СТОИМОСТЬ|СУММА|ПОЛОВИНА|СРОК)',full)
with ZipFile(output) as z:
 assert z.testzip() is None
 for n in z.namelist():
  if n.endswith(('.xml','.rels')):D.parseString(z.read(n))
(ROOT/'contract_text.txt').write_text(full)
audit={'output':str(output),'sha256':hashlib.sha256(output.read_bytes()).hexdigest(),'source':str(SOURCE),'changed_paragraphs':sorted(replacements),'unchanged_parties_and_requisites':True,'terms_confirmed':bool(terms)}
(ROOT/'validation.json').write_text(json.dumps(audit,ensure_ascii=False,indent=2))
print(json.dumps({'file':str(output),'size':output.stat().st_size,'terms_confirmed':bool(terms),'requisites_unchanged':True},ensure_ascii=False))
